CREATE TYPE "ExamDocumentType" AS ENUM ('QUESTION_PAPER', 'ANSWER_KEY', 'MARK_SHEET', 'SYLLABUS', 'INSTRUCTIONS', 'OTHER');
CREATE TABLE "exam_documents" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "schoolId" UUID NOT NULL, "examId" UUID NOT NULL, "classId" UUID, "subjectId" UUID, "type" "ExamDocumentType" NOT NULL, "storageKey" VARCHAR(512) NOT NULL, "originalFileName" VARCHAR(180) NOT NULL, "mimeType" VARCHAR(120) NOT NULL, "sizeBytes" INTEGER NOT NULL, "uploadedByUserId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_documents_pkey" PRIMARY KEY ("id"), CONSTRAINT "exam_documents_school_fkey" FOREIGN KEY ("schoolId") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "exam_documents_exam_fkey" FOREIGN KEY ("examId") REFERENCES "exams"("id") ON DELETE CASCADE, CONSTRAINT "exam_documents_class_fkey" FOREIGN KEY ("classId") REFERENCES "academic_classes"("id") ON DELETE RESTRICT, CONSTRAINT "exam_documents_subject_fkey" FOREIGN KEY ("subjectId") REFERENCES "subjects"("id") ON DELETE RESTRICT, CONSTRAINT "exam_documents_uploader_fkey" FOREIGN KEY ("uploadedByUserId") REFERENCES "user_profiles"("id") ON DELETE RESTRICT, CONSTRAINT "exam_documents_size_check" CHECK ("sizeBytes" > 0));
CREATE INDEX "exam_documents_school_exam_idx" ON "exam_documents"("schoolId", "examId");
CREATE INDEX "exam_documents_context_idx" ON "exam_documents"("schoolId", "examId", "classId", "subjectId");
